import math
from itertools import product

def compute_posterior(probs, guess, response):
    # probs: list of probabilities for targets 1..128 (index 0..127)
    # guess: 1-based index
    # response: 'higher', 'lower', or 'equals'
    g = guess - 1 # 0-based index
    n = len(probs)
    new_probs = [0.0] * n

    if response == 'equals':
        new_probs[g] = 1.0
    elif response == 'higher':
        # target > g: prob factor 0.7
        # target < g: prob factor 0.3
        # target = g: impossible if response is 'higher'
        sum_h = sum(probs[t] * 0.7 for t in range(g+1, n))
        sum_l = sum(probs[t] * 0.3 for t in range(0, g))
        total = sum_h + sum_l
        if total > 0:
            for t in range(g+1, n):
                new_probs[t] = probs[t] * 0.7 / total
            for t in range(0, g):
                new_probs[t] = probs[t] * 0.3 / total
    elif response == 'lower':
        # target < g: prob factor 0.7
        # target > g: prob factor 0.3
        sum_l = sum(probs[t] * 0.7 for t in range(0, g))
        sum_h = sum(probs[t] * 0.3 for t in range(g+1, n))
        total = sum_l + sum_h
        if total > 0:
            for t in range(0, g):
                new_probs[t] = probs[t] * 0.7 / total
            for t in range(g+1, n):
                new_probs[t] = probs[t] * 0.3 / total
    return new_probs

def entropy(probs):
    return -sum(p * math.log2(p) for p in probs if p > 0)

def expected_entropy(probs, guess):
    g = guess - 1
    n = len(probs)

    # Prob of each response
    p_eq = probs[g]

    # If equals, entropy is 0
    # We only need to compute for higher and lower

    # Posterior for higher
    sum_h = sum(probs[t] * 0.7 for t in range(g+1, n))
    sum_l_high = sum(probs[t] * 0.3 for t in range(0, g))
    p_high = sum_h + sum_l_high

    # Posterior for lower
    sum_l = sum(probs[t] * 0.7 for t in range(0, g))
    sum_h_low = sum(probs[t] * 0.3 for t in range(g+1, n))
    p_low = sum_l + sum_h_low

    if p_high == 0 and p_low == 0:
        return 0 # Should not happen unless p_eq = 1

    post_high = [0.0] * n
    if p_high > 0:
        for t in range(g+1, n):
            post_high[t] = probs[t] * 0.7 / p_high
        for t in range(0, g):
            post_high[t] = probs[t] * 0.3 / p_high

    post_low = [0.0] * n
    if p_low > 0:
        for t in range(0, g):
            post_low[t] = probs[t] * 0.7 / p_low
        for t in range(g+1, n):
            post_low[t] = probs[t] * 0.3 / p_low

    return p_high * entropy(post_high) + p_low * entropy(post_low)

def get_best_guess(probs):
    n = len(probs)
    best_g = 1
    best_ent = float('inf')

    for g in range(1, n+1):
        ent = expected_entropy(probs, g)
        if ent < best_ent:
            best_ent = ent
            best_g = g

    return best_g

# Initial uniform distribution
probs = [1.0/128] * 128
print("Initial best guess:", get_best_guess(probs))
