#!/usr/bin/env python3
"""
Bayesian solver for noisy binary search problem.
"""

import json
import os
import subprocess

GUESS_LOG = "/agent/guess_log.json"
NUM_TARGETS = 128
NOISE_PROB = 0.3

def load_log():
    """Load the guess log."""
    if os.path.exists(GUESS_LOG):
        with open(GUESS_LOG) as f:
            return json.load(f)
    max_guesses = int(os.environ.get("GAME_MAX_GUESSES", 8))
    return {"guesses": [], "responses": [], "guesses_remaining": max_guesses}

def make_guess(guess):
    """Make a guess and return the response."""
    result = subprocess.run(["./guess.py", str(guess)], capture_output=True, text=True)
    output = result.stdout.strip()
    print(f"Guessed {guess}: {output}")
    return output

def parse_response(output):
    """Parse the response string to get the direction."""
    if "equals" in output:
        return "equals"
    elif "higher" in output:
        return "higher"
    elif "lower" in output:
        return "lower"
    else:
        raise ValueError(f"Unknown response: {output}")

def initialize_posterior():
    """Initialize uniform posterior."""
    return [1.0 / NUM_TARGETS] * NUM_TARGETS

def compute_median(posterior):
    """Compute the median of the posterior distribution."""
    cumsum = 0.0
    for i in range(NUM_TARGETS):
        cumsum += posterior[i]
        if cumsum >= 0.5:
            return i + 1  # Convert 0-indexed to 1-indexed
    return NUM_TARGETS

def update_posterior(posterior, query, response):
    """Update the posterior based on the query and response."""
    new_posterior = [0.0] * NUM_TARGETS
    total = 0.0

    for x in range(NUM_TARGETS):
        target_val = x + 1  # Convert 0-indexed to 1-indexed

        if response == "equals":
            # Likelihood is 1 if target equals query, 0 otherwise
            if target_val == query:
                likelihood = 1.0
            else:
                likelihood = 0.0
        elif response == "higher":
            # True response is "higher" with prob 0.7, "lower" with prob 0.3
            if target_val > query:
                likelihood = 0.7
            elif target_val < query:
                likelihood = 0.3
            else:
                likelihood = 0.0
        elif response == "lower":
            # True response is "lower" with prob 0.7, "higher" with prob 0.3
            if target_val < query:
                likelihood = 0.7
            elif target_val > query:
                likelihood = 0.3
            else:
                likelihood = 0.0
        else:
            raise ValueError(f"Unknown response: {response}")

        new_posterior[x] = posterior[x] * likelihood
        total += new_posterior[x]

    # Normalize
    if total > 0:
        new_posterior = [p / total for p in new_posterior]
    else:
        # Fallback to uniform
        new_posterior = [1.0 / NUM_TARGETS] * NUM_TARGETS

    return new_posterior

def main():
    log = load_log()
    posterior = initialize_posterior()

    # Apply previous guesses if any
    for guess, response_str in zip(log["guesses"], log["responses"]):
        response = parse_response(response_str)
        posterior = update_posterior(posterior, guess, response)

    print(f"Starting with {log['guesses_remaining']} guesses remaining")
    print(f"Current posterior max at: {posterior.index(max(posterior)) + 1} with prob {max(posterior)}")

    # Make remaining guesses
    while log["guesses_remaining"] > 0:
        query = compute_median(posterior)
        print(f"Querying: {query}")

        output = make_guess(query)
        response = parse_response(output)

        posterior = update_posterior(posterior, query, response)
        log = load_log()  # Reload log to get updated guesses_remaining

        print(f"Posterior max at: {posterior.index(max(posterior)) + 1} with prob {max(posterior)}")

        if response == "equals":
            print(f"Found the target: {query}")
            break

    # The best answer is the target with highest posterior probability
    best_target = posterior.index(max(posterior)) + 1
    print(f"Best target: {best_target}")

    # Submit the answer
    from submit import submit
    submit(best_target)

if __name__ == "__main__":
    main()
