    new_weights = [0.0] * (len(weights) + 1)  # 1-indexed
    if response == "equals":
        # Secret equals the guess
        new_weights[guess] = 1.0
    elif response == "higher":
        # True response is "higher" with prob 0.7 (secret > guess)
        # True response is "lower" with prob 0.3 (secret < guess), but noise flipped it
        for x in range(1, len(weights) + 1):
            if x > guess:
                new_weights[x] = weights[x] * 0.7
            elif x < guess:
                new_weights[x] = weights[x] * 0.3
            else:
                new_weights[x] = 0.0  # x == guess, response was not equals
    elif response == "lower":
        # True response is "lower" with prob 0.7 (secret < guess)
        # True response is "higher" with prob 0.3 (secret > guess), but noise flipped it
        for x in range(1, len(weights) + 1):
            if x < guess:
                new_weights[x] = weights[x] * 0.7
            elif x > guess:
                new_weights[x] = weights[x] * 0.3
            else:
                new_weights[x] = 0.0  # x == guess, response was not equals

    # Normalize
    total = sum(new_weights)
    if total > 0:
        new_weights = [w / total for w in new_weights]

    return new_weights

def expected_entropy(weights, guess):
    """Calculate expected entropy after making a query."""
    # If secret > guess, we get "higher" with prob 0.7, "lower" with prob 0.3
    prob_secret_gt = sum(weights[guess+1:])
    prob_secret_lt = sum(weights[1:guess])
    prob_secret_eq = weights[guess]

    # Expected entropy
    # If response is "higher" (prob = prob_secret_gt * 0.7 + prob_secret_lt * 0.3)
    prob_higher = prob_secret_gt * 0.7 + prob_secret_lt * 0.3
    # If response is "lower" (prob = prob_secret_lt * 0.7 + prob_secret_gt * 0.3)
    prob_lower = prob_secret_lt * 0.7 + prob_secret_gt * 0.3
    # If response is "equals" (prob = prob_secret_eq)
    prob_equals = prob_secret_eq

    # Calculate entropy of posterior for each response
    def entropy_of_posterior(posterior_weights):
        ent = 0.0
        for w in posterior_weights:
            if w > 1e-10:
                ent -= w * math.log2(w)
        return ent

    # Posterior if response is "higher"
    post_higher = [0.0] * (len(weights) + 1)
    for x in range(1, len(weights) + 1):
        if x > guess:
            post_higher[x] = weights[x] * 0.7
        elif x < guess:
            post_higher[x] = weights[x] * 0.3
    total_h = sum(post_higher)
    if total_h > 0:
        post_higher = [w / total_h for w in post_higher]

    # Posterior if response is "lower"
    post_lower = [0.0] * (len(weights) + 1)
    for x in range(1, len(weights) + 1):
        if x < guess:
            post_lower[x] = weights[x] * 0.7
        elif x > guess:
            post_lower[x] = weights[x] * 0.3
    total_l = sum(post_lower)
    if total_l > 0:
        post_lower = [w / total_l for w in post_lower]

    # Posterior if response is "equals"
    post_equals = [0.0] * (len(weights) + 1)
    post_equals[guess] = 1.0

    expected_ent = 0.0
    if prob_higher > 1e-10:
        expected_ent += prob_higher * entropy_of_posterior(post_higher)
    if prob_lower > 1e-10:
        expected_ent += prob_lower * entropy_of_posterior(post_lower)
    if prob_equals > 1e-10:
        expected_ent += prob_equals * entropy_of_posterior(post_equals)

    return expected_ent

def solve():
    log = load_log()

    # Initialize uniform weights over [1, 128]
    N = 128
    weights = [0.0] + [1.0 / N] * N  # 1-indexed, weights[0] is unused

    # Process existing guesses
    for i in range(len(log["guesses"])):
        weights = update_weights(weights, log["guesses"][i], log["responses"][i])

    remaining = log["guesses_remaining"]

    for query_num in range(remaining):
        # Find the best guess to make
        best_guess = 1
        best_expected_ent = float('inf')

        for g in range(1, N + 1):
            ent = expected_entropy(weights, g)
            if ent < best_expected_ent:
                best_expected_ent = ent
                best_guess = g

        print(f"Query {query_num + 1}/{remaining}: guessing {best_guess}, expected entropy {best_expected_ent:.4f}")

        # Make the guess
        response_text = make_guess(best_guess)
        print(f"Response: {response_text}")

        # Parse response
        if "equals" in response_text:
            print(f"Found the secret: {best_guess}")
            # Update weights to confirm
            weights = update_weights(weights, best_guess, "equals")
            # Submit immediately
            return best_guess
        elif "higher" in response_text:
            response = "higher"
        else:
            response = "lower"

        # Update weights
        weights = update_weights(weights, best_guess, response)

        # Check if we have a clear winner
        max_weight = max(weights[1:])
        max_index = weights.index(max_weight)
        print(f"After update: max weight {max_weight:.6f} at index {max_index}")

    # If we've exhausted all queries, submit the most likely answer
    max_weight = max(weights[1:])
    answer = weights.index(max_weight)
    print(f"Final answer: {answer} with weight {max_weight:.6f}")
    return answer

if __name__ == "__main__":
    answer = solve()
    print(f"Submitting answer: {answer}")
    # We'll call submit separately after seeing the output
