import json
import os
import subprocess
import math

def entropy(probs):
    h = 0.0
    for p in probs:
        if p > 1e-12:
            h -= p * math.log2(p)
    return h

def load_log():
    log_path = "/agent/guess_log.json"
    if os.path.exists(log_path):
        with open(log_path) as f:
            return json.load(f)
    max_guesses = int(os.environ.get("GAME_MAX_GUESSES", "8"))
    return {"guesses": [], "responses": [], "guesses_remaining": max_guesses}

def update_distribution(probs, guess, response):
    """Update probability distribution based on guess and response."""
    new_probs = [0.0] * 128
    if response == "equals":
        new_probs[guess - 1] = 1.0
        return new_probs

    # For non-equal responses
    # If response is "higher", true target > guess with prob 0.7, < guess with prob 0.3
    # If response is "lower", true target < guess with prob 0.7, > guess with prob 0.3

    factor = [0.0] * 128
    for t in range(128):
        true_t = t + 1
        if true_t == guess:
            factor[t] = 0.0  # Should not happen if response is not equals
        elif response == "higher":
            if true_t > guess:
                factor[t] = 0.7
            else:
                factor[t] = 0.3
        elif response == "lower":
            if true_t < guess:
                factor[t] = 0.7
            else:
                factor[t] = 0.3

        new_probs[t] = probs[t] * factor[t]

    # Normalize
    total = sum(new_probs)
    if total > 1e-12:
        new_probs = [p / total for p in new_probs]
    else:
        # Uniform fallback (should not happen)
        new_probs = [1.0 / 128] * 128

    return new_probs

def expected_entropy(probs, guess):
    """Compute expected entropy if we make a specific guess."""
    p_eq = probs[guess - 1]
    p_hi = sum(probs[t] * (0.7 if t + 1 > guess else 0.3) for t in range(128) if t + 1 != guess)
    p_lo = sum(probs[t] * (0.3 if t + 1 > guess else 0.7) for t in range(128) if t + 1 != guess)

    # Posterior distributions
    if p_eq > 1e-12:
        h_eq = 0.0  # Equals gives entropy 0
    else:
        h_eq = 0.0

    if p_hi > 1e-12:
        posterior_hi = [probs[t] * (0.7 if t + 1 > guess else 0.3) for t in range(128) if t + 1 != guess]
        # Need to include t=guess-1 with prob 0
        posterior_hi_full = [0.0] * 128
        for t in range(128):
            if t + 1 != guess:
                posterior_hi_full[t] = probs[t] * (0.7 if t + 1 > guess else 0.3)
            else:
                posterior_hi_full[t] = 0.0
        total_hi = sum(posterior_hi_full)
        posterior_hi_norm = [p / total_hi for p in posterior_hi_full]
        h_hi = entropy(posterior_hi_norm)
    else:
        h_hi = 0.0

    if p_lo > 1e-12:
        posterior_lo_full = [0.0] * 128
        for t in range(128):
            if t + 1 != guess:
                posterior_lo_full[t] = probs[t] * (0.3 if t + 1 > guess else 0.7)
            else:
                posterior_lo_full[t] = 0.0
        total_lo = sum(posterior_lo_full)
        posterior_lo_norm = [p / total_lo for p in posterior_lo_full]
        h_lo = entropy(posterior_lo_norm)
    else:
        h_lo = 0.0

    exp_h = p_eq * h_eq + p_hi * h_hi + p_lo * h_lo
    return exp_h

def main():
    log = load_log()
    noise_prob = float(os.environ.get("GAME_NOISE_PROB", "0.3"))

    # Initialize uniform distribution
    probs = [1.0 / 128] * 128

    # Process any existing guesses
    for i in range(len(log["guesses"])):
        probs = update_distribution(probs, log["guesses"][i], log["responses"][i])

    # Make new guesses
    while log["guesses_remaining"] > 0:
        # Find optimal guess
        best_guess = 1
        best_exp_entropy = float('inf')

        for g in range(1, 129):
            exp_h = expected_entropy(probs, g)
            if exp_h < best_exp_entropy:
                best_exp_entropy = exp_h
                best_guess = g

        # Make the guess
        result = subprocess.run(["./guess.py", str(best_guess)], capture_output=True, text=True)
        print(f"Guess {best_guess}: {result.stdout.strip()}")

        # Parse response
        output = result.stdout.strip()
        if "equals" in output:
            response = "equals"
        elif "higher" in output:
            response = "higher"
        elif "lower" in output:
            response = "lower"
        else:
            print(f"Unexpected response: {output}")
            break

        # Update log
        log["guesses"].append(best_guess)
        log["responses"].append(response)
        log["guesses_remaining"] -= 1

        with open("/agent/guess_log.json", "w") as f:
            json.dump(log, f, indent=2)

        # Update distribution
        probs = update_distribution(probs, best_guess, response)

        if response == "equals":
            print(f"Found the secret number: {best_guess}")
            break

    # Submit the most likely number
    max_prob = max(probs)
    best_t = probs.index(max_prob) + 1
    print(f"Submitting: {best_t}")

    # Write answer to a file for submission
    with open("/agent/answer.txt", "w") as f:
        f.write(str(best_t))

if __name__ == "__main__":
    main()
