        posterior_hi_full = [0.0] * 128
        for t in range(128):
            if t + 1 != guess:
                posterior_hi_full[t] = probs[t] * (0.7 if t + 1 > guess else 0.3)
            else:
                posterior_hi_full[t] = 0.0
        total_hi = sum(posterior_hi_full)
        posterior_hi_norm = [p / total_hi for p in posterior_hi_full]
        h_hi = entropy(posterior_hi_norm)
    else:
        h_hi = 0.0

    if p_lo > 1e-12:
        posterior_lo_full = [0.0] * 128
        for t in range(128):
            if t + 1 != guess:
                posterior_lo_full[t] = probs[t] * (0.3 if t + 1 > guess else 0.7)
            else:
                posterior_lo_full[t] = 0.0
        total_lo = sum(posterior_lo_full)
        posterior_lo_norm = [p / total_lo for p in posterior_lo_full]
        h_lo = entropy(posterior_lo_norm)
    else:
        h_lo = 0.0

    exp_h = p_eq * h_eq + p_hi * h_hi + p_lo * h_lo
    return exp_h

def main():
    log = load_log()
    noise_prob = float(os.environ.get("GAME_NOISE_PROB", "0.3"))

    # Initialize uniform distribution
    probs = [1.0 / 128] * 128

    # Process any existing guesses
    for i in range(len(log["guesses"])):
        probs = update_distribution(probs, log["guesses"][i], log["responses"][i])

    # Make new guesses
    while log["guesses_remaining"] > 0:
        # Find optimal guess
        best_guess = 1
        best_exp_entropy = float('inf')

        for g in range(1, 129):
            exp_h = expected_entropy(probs, g)
            if exp_h < best_exp_entropy:
                best_exp_entropy = exp_h
                best_guess = g

        # Make the guess
        result = subprocess.run(["./guess.py", str(best_guess)], capture_output=True, text=True)
        print(f"Guess {best_guess}: {result.stdout.strip()}")

        # Parse response
        output = result.stdout.strip()
        if "equals" in output:
            response = "equals"
        elif "higher" in output:
            response = "higher"
        elif "lower" in output:
            response = "lower"
        else:
            print(f"Unexpected response: {output}")
            break

        # Update log
        log["guesses"].append(best_guess)
        log["responses"].append(response)
        log["guesses_remaining"] -= 1

        with open("/agent/guess_log.json", "w") as f:
            json.dump(log, f, indent=2)

        # Update distribution
        probs = update_distribution(probs, best_guess, response)

        if response == "equals":
            print(f"Found the secret number: {best_guess}")
            break

    # Submit the most likely number
    max_prob = max(probs)
    best_t = probs.index(max_prob) + 1
    print(f"Submitting: {best_t}")

    # Write answer to a file for submission
    with open("/agent/answer.txt", "w") as f:
        f.write(str(best_t))

if __name__ == "__main__":
