#!/usr/bin/env python3
import json
import subprocess
import math
import os

GUESS_LOG = "/agent/guess_log.json"
NOISE = 0.3  # 30% noise

def get_response(guess):
    """Make a guess and get the response"""
    result = subprocess.run(['python3', '/agent/guess.py', str(guess)], 
                          capture_output=True, text=True)
    output = result.stdout.strip()
    # Parse response
    if 'equals' in output:
        return 'equals'
    elif 'higher' in output:
        return 'higher'
    elif 'lower' in output:
        return 'lower'
    else:
        print(f"Unexpected output: {output}")
        return None

def update_probs(probs, guess, response):
    """Update probability distribution based on response"""
    new_probs = {}
    total = 0

    for num, p in probs.items():
        if num == guess:
            # If num == guess, true_response is "equals"
            if response == 'equals':
                new_probs[num] = p * 1.0  # correct
            else:
                new_probs[num] = p * 0.0  # impossible (noise doesn't apply to equals)
        elif num < guess:
            # True answer is "lower"
            if response == 'lower':
                new_probs[num] = p * (1 - NOISE)  # correct
            elif response == 'higher':
                new_probs[num] = p * NOISE  # flipped
            else:  # equals
                new_probs[num] = p * 0.0
        elif num > guess:
            # True answer is "higher"
            if response == 'higher':
                new_probs[num] = p * (1 - NOISE)  # correct
            elif response == 'lower':
                new_probs[num] = p * NOISE  # flipped
            else:  # equals
                new_probs[num] = p * 0.0

        total += new_probs[num]

    # Normalize
    if total > 0:
        for num in new_probs:
            new_probs[num] /= total

    return new_probs

def entropy(probs):
    """Calculate entropy of distribution"""
    ent = 0
    for p in probs.values():
        if p > 0:
            ent -= p * math.log2(p)
    return ent

def expected_entropy(probs, guess):
    """Calculate expected entropy after querying guess"""
    expected = 0

    # Calculate probabilities of each response
    prob_equals = probs.get(guess, 0)
    prob_higher = sum(probs.get(num, 0) for num in probs if num > guess)
    prob_lower = sum(probs.get(num, 0) for num in probs if num < guess)

    # If we get "equals"
    if prob_equals > 0:
        new_probs_eq = {guess: 1.0}
        expected += prob_equals * entropy(new_probs_eq)

    # If we get "higher"
    p_response_higher = prob_higher * (1 - NOISE) + prob_lower * NOISE

    if p_response_higher > 0:
        new_probs_high = {}
        for num in probs:
            if num > guess:
                new_probs_high[num] = probs[num] * (1 - NOISE)
            elif num < guess:
                new_probs_high[num] = probs[num] * NOISE
            else:
                new_probs_high[num] = 0
        total = sum(new_probs_high.values())
        if total > 0:
            for num in new_probs_high:
                new_probs_high[num] /= total
        expected += p_response_higher * entropy(new_probs_high)

    # If we get "lower"
    p_response_lower = prob_higher * NOISE + prob_lower * (1 - NOISE)

    if p_response_lower > 0:
        new_probs_low = {}
        for num in probs:
            if num > guess:
                new_probs_low[num] = probs[num] * NOISE
            elif num < guess:
                new_probs_low[num] = probs[num] * (1 - NOISE)
            else:
                new_probs_low[num] = 0
        total = sum(new_probs_low.values())
        if total > 0:
            for num in new_probs_low:
                new_probs_low[num] /= total
        expected += p_response_lower * entropy(new_probs_low)

    return expected

# Initialize uniform distribution
probs = {i: 1.0/128 for i in range(1, 129)}

# Check if we have a guess log
guesses_made = 0
if os.path.exists(GUESS_LOG):
    with open(GUESS_LOG) as f:
        log = json.load(f)
    guesses_made = len(log['guesses'])
    print(f"Guesses already made: {guesses_made}")
    print(f"Remaining: {log['guesses_remaining']}")

    # Use the responses from log to initialize our probability distribution
    for guess, response in zip(log['guesses'], log['responses']):
        probs = update_probs(probs, guess, response)
        print(f"After guessing {guess}, response: {response}, best: {max(probs, key=probs.get)} with prob {max(probs.values()):.4f}")
else:
    log = {"guesses": [], "responses": [], "guesses_remaining": 8}
    print("No previous guesses found. Starting fresh.")

# Now make optimal guesses
remaining = log['guesses_remaining']
for i in range(remaining):
    current_entropy = entropy(probs)
    print(f"\n=== Round {guesses_made + i + 1} ===")
    print(f"Current entropy: {current_entropy:.4f}")
    print(f"Top 5 candidates: {sorted(probs.items(), key=lambda x: -x[1])[:5]}")

    # Find the guess that minimizes expected entropy
    best_guess = None
    best_expected_entropy = float('inf')

    for g in range(1, 129):
        exp_ent = expected_entropy(probs, g)
        if exp_ent < best_expected_entropy:
            best_expected_entropy = exp_ent
            best_guess = g

    print(f"Optimal guess: {best_guess}, expected entropy after: {best_expected_entropy:.4f}")

    # Make the guess
    response = get_response(best_guess)
    print(f"Response: {response}")

    # Update probabilities
    probs = update_probs(probs, best_guess, response)
    print(f"After update, best: {max(probs, key=probs.get)} with prob {max(probs.values()):.4f}")

    if response == 'equals':
        print(f"Found it! The answer is {best_guess}")
        break

# Final answer
answer = max(probs, key=probs.get)
print(f"\nFinal answer: {answer}")
print(f"Top 10: {sorted(probs.items(), key=lambda x: -x[1])[:10]}")

# Save the answer
with open('/tmp/answer.txt', 'w') as f:
    f.write(str(answer))
